// Parse e prepara para upsert
const resp = $input.first().json;
const choices = resp.choices || [];
if (choices.length === 0) return [{ json: { skip: true } }];

let parsed = {};
try {
  parsed = JSON.parse(choices[0].message.content);
} catch (e) {
  parsed = { resumo: choices[0].message.content, topicos: [], perfil_inferido: '', proximos_passos: '' };
}

const mobile = $('Variáveis').first().json.mobile;
return [{
  json: {
    telefone: mobile,
    resumo: parsed.resumo || '',
    topicos: Array.isArray(parsed.topicos) ? parsed.topicos.join(', ') : (parsed.topicos || ''),
    perfil_inferido: parsed.perfil_inferido || '',
    proximos_passos: parsed.proximos_passos || '',
    status_atendimento_apos: $('Resolver Sessão').first().json.status_atendimento || 'ativo',
    created_at: new Date().toISOString()
  }
}];

const body = $input.first().json.body || $input.first().json;
const startDay = body.startDay || new Date().toISOString().slice(0,10);
const endDay = body.endDay || startDay;
const audiencia = (body.audiencia || 'B2B').toUpperCase();
const force = body.force === true || body.force === 'true';

const cacheKey = `grdmad:calcache:${startDay}_${endDay}_${audiencia}`;
return [{ json: { startDay, endDay, audiencia, cacheKey, force } }];

// Mescla os 3 calendários e calcula slots livres
// Horario comercial unico: seg-sex 08:00-17:45 (slots de 30 min)
// Pula finais de semana e feriados nacionais/SP
const input = $('Cal: Parse Input').first().json;
const principal = $('Cal: GET Principal').all().map(i => i.json);
const b2b = $('Cal: GET B2B').all().map(i => i.json);
const b2c = $('Cal: GET B2C').all().map(i => i.json);

// Feriados nacionais e de SP
const feriados = ["2026-01-01", "2026-02-16", "2026-02-17", "2026-04-03", "2026-04-21", "2026-05-01", "2026-06-04", "2026-07-09", "2026-09-07", "2026-10-12", "2026-11-02", "2026-11-15", "2026-11-20", "2026-12-25", "2027-01-01", "2027-02-08", "2027-02-09", "2027-03-26", "2027-04-21", "2027-05-01", "2027-05-27", "2027-07-09", "2027-09-07", "2027-10-12", "2027-11-02", "2027-11-15", "2027-11-20", "2027-12-25"];

// Coletar todos os busy intervals
const busy = [...principal, ...b2b, ...b2c].map(e => {
  const s = e?.start?.dateTime || e?.start?.date;
  const en = e?.end?.dateTime || e?.end?.date;
  if (!s || !en) return null;
  return { start: new Date(s).getTime(), end: new Date(en).getTime(), summary: e.summary || '' };
}).filter(Boolean).sort((a, b) => a.start - b.start);

// Configuracao de horario unico
const slotMinutes = 30;
const horaInicio = 8;     // 08:00
const minutoInicio = 0;
const horaFim = 17;       // 17:45 - último slot começa às 17:15 (acaba 17:45)
const minutoFim = 45;

const slots_livres = [];
const slots_ocupados = [];

const startD = new Date(input.startDay + 'T00:00:00-03:00');
const endD = new Date(input.endDay + 'T23:59:59-03:00');

function pad(n) { return n < 10 ? '0' + n : String(n); }
function toISO(d) {
  const yyyy = d.getFullYear();
  const mm = pad(d.getMonth() + 1);
  const dd = pad(d.getDate());
  const HH = pad(d.getHours());
  const MM = pad(d.getMinutes());
  return `${yyyy}-${mm}-${dd}T${HH}:${MM}:00-03:00`;
}

for (let d = new Date(startD); d <= endD; d.setDate(d.getDate() + 1)) {
  const dow = d.getDay(); // 0=dom, 6=sab
  if (dow === 0 || dow === 6) continue; // pula fim de semana

  const dateStr = d.toISOString().slice(0, 10);

  // Pula feriados
  if (feriados.includes(dateStr)) continue;

  // Construir slots de 30min entre 08:00 e 17:45
  const startMinutes = horaInicio * 60 + minutoInicio; // 480
  const endMinutes = horaFim * 60 + minutoFim;          // 1065

  for (let totalMin = startMinutes; totalMin + slotMinutes <= endMinutes + slotMinutes; totalMin += slotMinutes) {
    const h = Math.floor(totalMin / 60);
    const m = totalMin % 60;
    if (h > horaFim || (h === horaFim && m > minutoFim - slotMinutes)) break;

    const slotStart = new Date(d);
    slotStart.setHours(h, m, 0, 0);
    const slotEnd = new Date(slotStart.getTime() + slotMinutes * 60 * 1000);

    const slotStartTs = slotStart.getTime();
    const slotEndTs = slotEnd.getTime();

    // Checar conflito com busy
    const conflito = busy.find(b => b.start < slotEndTs && b.end > slotStartTs);

    const slotInfo = {
      date: dateStr,
      time: pad(h) + ':' + pad(m),
      startISO: toISO(slotStart),
      endISO: toISO(slotEnd),
      diaSemana: ['domingo','segunda','terca','quarta','quinta','sexta','sabado'][dow]
    };

    if (conflito) {
      slots_ocupados.push({ ...slotInfo, conflito_com: conflito.summary });
    } else {
      slots_livres.push(slotInfo);
    }
  }
}

return [{
  json: {
    audiencia: input.audiencia,
    startDay: input.startDay,
    endDay: input.endDay,
    slots_livres,
    slots_ocupados,
    total_livres: slots_livres.length,
    total_ocupados: slots_ocupados.length
  }
}];

